import json

def note(name_oct):
    """Convert note name like 'C-4' or 'C#4' to FT2 note number (0-95)"""
    # Handle both C-4 and C#4 formats
    if '#' in name_oct:
        # C#4 format
        name = name_oct[:2]
        octave = int(name_oct[2:])
    else:
        # C-4 format
        name = name_oct[0]
        octave = int(name_oct[2:])
    note_map = {'C':0, 'C#':1, 'D':2, 'D#':3, 'E':4, 'F':5, 'F#':6, 'G':7, 'G#':8, 'A':9, 'A#':10, 'B':11}
    return note_map[name] + octave * 12

# Test
print(note('C-4'), note('C#4'), note('D-4'), note('D#4'), note('E-4'), note('F-4'), note('F#4'), note('G-4'), note('G#4'), note('A-4'), note('A#4'), note('B-4'))

# Channel assignments:
# 0: Lead
# 1: Bass  
# 2: Pad
# 3: Kick
# 4: Snare
# 5: Hi-hat (closed)
# 6: Arp/Pluck
# 7: Open Hi-hat / FX

patterns = []

# ============================================================
# PATTERN 0: Intro (rows 0-63) - Pad fade in, arpeggio, hats
# ============================================================
p = [[] for _ in range(64)]
for row in range(64):
    # Pad on ch 2 - trigger at row 0, sustained
    if row == 0:
        p[row].append((2, note('C-3'), 3, 20, 0, 0))
    # Arp on ch 6 - 16th notes
    if row % 4 == 0:
        arp_seq = [note('C-5'), note('D#5'), note('G-5'), note('A#5'), note('C-6'), note('A#5'), note('G-5'), note('D#5')]
        idx = (row // 4) % len(arp_seq)
        p[row].append((6, arp_seq[idx], 8, 40, 0, 0))
    # Closed hat on ch 5 - 8th notes
    if row % 2 == 0:
        p[row].append((5, note('C-4'), 6, 25, 0, 0))
    # Kick on ch 3 - on the 1 and 3 (rows 0, 16, 32, 48)
    if row % 16 == 0:
        p[row].append((3, note('C-4'), 4, 64, 0, 0))
patterns.append(p)

# ============================================================
